// Wireless audio index — record JAH-GPCS-AUDIOTRANSMITTER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"latency_ms": 25, "range_m": 15};
var value = (1000/m.latency_ms*m.range_m);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-AUDIOTRANSMITTER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-AUDIOTRANSMITTER-000001|' + value.toFixed(2) + ' audio index');

